pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        vm.prank(caller);
        bool succeeded;
        try c.assertionResolvedCallback(bytes32(uint256(1)), true) {
            succeeded = true;
        } catch {
            succeeded = false;
        }
        assertTrue(!succeeded);
    }
}
